installer-gui-script.script:
function premiereInstalled() {
  for (var year = 2022; year <= 2035; year++) {
    var app = '/Applications/Adobe Premiere Pro ' + year + '/Adobe Premiere Pro ' + year + '.app';
    if (system.files.fileExistsAtPath(app)) { return true; }
  }
  return system.files.fileExistsAtPath('/Applications/Adobe Premiere Pro (Beta)/Adobe Premiere Pro (Beta).app');
}
function resolveInstalled() {
  return system.files.fileExistsAtPath('/Applications/DaVinci Resolve/DaVinci Resolve.app');
}
function installationCheck() {
  if (system.compareVersions(system.version.ProductVersion, '12.0') < 0) {
    my.result.title = 'macOS 12 or newer required';
    my.result.message = 'ICG supports macOS 12 Monterey and newer.';
    my.result.type = 'Fatal';
    return false;
  }
  if (!premiereInstalled() && !resolveInstalled()) {
    my.result.title = 'No supported Host found';
    my.result.message = 'Neither Adobe Premiere Pro nor DaVinci Resolve was found in /Applications. You can still install and the panel will appear once a Host is installed.';
    my.result.type = 'Warn';
    return false;
  }
  return true;
}
